#include <stdio.h>



int main(void) {
    int r, c, a[20][20], found = 0;
    scanf("%d%d", &r, &c);
    for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) scanf("%d", &a[i][j]);
    for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) {
        int ok = 1;
        for (int k = 0; k < c; k++) if (a[i][k] > a[i][j]) ok = 0;
        for (int k = 0; k < r; k++) if (a[k][j] < a[i][j]) ok = 0;
        if (ok) { printf("%d %d %d\n", a[i][j], i + 1, j + 1); found = 1; }
    }
    if (!found) puts("NONE");
    return 0;
}
